<script setup lang="ts">
import { ref } from 'vue'; import Button from 'primevue/button'; import DataTable from 'primevue/datatable'; import Column from 'primevue/column'; import Dialog from 'primevue/dialog'; import InputNumber from 'primevue/inputnumber'; import InputText from 'primevue/inputtext'; import Select from 'primevue/select'; import Textarea from 'primevue/textarea'; import { useToast } from 'primevue/usetoast'; import { api,currentUser,downloadCsv } from '../lib/api'; import { useQuery } from '../composables/useQuery'; import { money,date,type Data } from '../lib/types'; import StatusBadge from '../components/StatusBadge.vue'; import QueryState from '../components/QueryState.vue';
const {data,loading,error,refresh}=useQuery(()=>api('/admin/finance'));const tab=ref('payments'),show=ref(false),journal=ref<Data>(),journalVisible=ref(false),busy=ref(false),toast=useToast();const form=ref({driverId:'',amount:0,reference:'',evidence:''});
async function save(){busy.value=true;try{await api('/admin/cash-remittances',{method:'POST',body:form.value,idempotent:true});show.value=false;await refresh();toast.add({severity:'success',summary:'Đã lập đề nghị. Cần người phê duyệt độc lập.',life:4000});}catch(e){toast.add({severity:'error',summary:(e as Error).message,life:5000});}finally{busy.value=false;}}
async function approve(r:Data){busy.value=true;try{await api('/admin/cash-remittances/'+r.id+'/approve',{method:'POST',body:{expectedVersion:r.version},idempotent:true});await refresh();toast.add({severity:'success',summary:'Đã xác nhận nộp công nợ và ghi sổ',life:3000});}catch(e){toast.add({severity:'error',summary:(e as Error).message,life:5000});}finally{busy.value=false;}}
function exportRows(){downloadCsv('grap-doi-soat-trang-hien-tai.csv',data.value?.payments??[],{rideCode:'Mã chuyến',driverName:'Tài xế',payableAmount:'Phải thu',paidAmount:'Đã thu',status:'Trạng thái'});}
</script>
<template><div class="page-heading"><div><div class="eyebrow">TÀI CHÍNH MINH BẠCH</div><h1>Tài chính & đối soát<span class="green-text">.</span></h1><p>Theo dõi nghĩa vụ thanh toán và sổ cái bất biến.</p></div><div class="heading-actions"><Button label="Làm mới" icon="pi pi-refresh" severity="secondary" outlined :loading="loading" @click="refresh"/><Button label="Xuất khoản thu đã tải" icon="pi pi-download" severity="secondary" outlined :disabled="!data" @click="exportRows"/><Button v-if="currentUser?.role==='FinanceOperator'" label="Lập đề nghị nộp công nợ" icon="pi pi-plus" @click="show=true"/></div></div><QueryState :loading="loading" :error="error" @retry="refresh"/><template v-if="data"><div class="metric-grid three"><div class="metric-card"><div class="metric-top"><span>Tổng nghĩa vụ phải thu</span><span class="metric-icon blue"><i class="pi pi-receipt"></i></span></div><div class="metric-value compact-number">{{money(data.totalPayable)}}</div><p class="muted">Các chuyến đã hoàn tất</p></div><div class="metric-card"><div class="metric-top"><span>Tiền mặt đã ghi nhận</span><span class="metric-icon green"><i class="pi pi-wallet"></i></span></div><div class="metric-value compact-number">{{money(data.collected)}}</div><p class="muted">Tiền do tài xế thực tế đã thu</p></div><div class="metric-card"><div class="metric-top"><span>Khách còn phải thanh toán</span><span class="metric-icon orange"><i class="pi pi-clock"></i></span></div><div class="metric-value compact-number">{{money(data.outstanding)}}</div><p class="muted">Giữ độc lập với trạng thái chuyến</p></div></div><section class="panel"><div class="tabs"><button v-for="(label,key) in {payments:'Khoản thu chuyến',balances:'Số dư & công nợ',journals:'Sổ cái',remittances:'Đề nghị nộp tiền'}" :key="key" :class="{active:tab===key}" @click="tab=key">{{label}}</button></div><DataTable v-if="tab==='payments'" :value="data.payments" paginator :rows="10" class="grap-table"><template #empty><div class="table-empty">Chưa có khoản thu chuyến.</div></template><Column field="rideCode" header="MÃ CHUYẾN"/><Column field="driverName" header="TÀI XẾ"/><Column header="PHẢI THU"><template #body="{data:d}">{{money(d.payableAmount)}}</template></Column><Column header="ĐÃ THU"><template #body="{data:d}">{{money(d.paidAmount)}}</template></Column><Column header="CÒN LẠI"><template #body="{data:d}"><strong>{{money(d.payableAmount-d.paidAmount)}}</strong></template></Column><Column header="KẾT QUẢ"><template #body="{data:d}"><StatusBadge :status="d.status"/></template></Column></DataTable><DataTable v-else-if="tab==='balances'" :value="data.drivers" class="grap-table"><template #empty><div class="table-empty">Chưa có số dư tài xế trong vùng.</div></template><Column field="name" header="TÀI XẾ"/><Column header="KHẢ DỤNG"><template #body="{data:d}">{{money(d.balance.available)}}</template></Column><Column header="ĐANG GIỮ"><template #body="{data:d}">{{money(d.balance.held)}}</template></Column><Column header="CÔNG NỢ"><template #body="{data:d}"><strong :class="{'form-error':d.balance.debt>0}">{{money(d.balance.debt)}}</strong></template></Column></DataTable><DataTable v-else-if="tab==='journals'" :value="data.journals" paginator :rows="10" class="grap-table"><template #empty><div class="table-empty">Chưa có bút toán được ghi nhận.</div></template><Column header="BÚT TOÁN"><template #body="{data:d}"><strong>{{d.description}}</strong><small class="cell-muted">{{date(d.createdAt)}}</small></template></Column><Column header="NỢ / CÓ"><template #body="{data:d}">{{money(d.entries.reduce((sum:number,e:Data)=>sum+e.debit,0))}}</template></Column><Column header="KIỂM TRA"><template #body="{data:d}"><StatusBadge :status="d.entries.reduce((sum:number,e:Data)=>sum+e.debit-e.credit,0)===0?'APPROVED':'REJECTED'" :label="d.entries.reduce((sum:number,e:Data)=>sum+e.debit-e.credit,0)===0?'Cân bằng':'Sai lệch'"/></template></Column><Column><template #body="{data:d}"><Button label="Chi tiết" text size="small" @click="journal=d;journalVisible=true"/></template></Column></DataTable><DataTable v-else :value="data.remittances" class="grap-table"><template #empty><div class="table-empty">Chưa có đề nghị nộp tiền.</div></template><Column field="reference" header="THAM CHIẾU"/><Column header="SỐ TIỀN"><template #body="{data:d}">{{money(d.amount)}}</template></Column><Column field="evidence" header="BẰNG CHỨNG"/><Column header="TRẠNG THÁI"><template #body="{data:d}"><StatusBadge :status="d.status"/></template></Column><Column><template #body="{data:d}"><Button v-if="currentUser?.role==='FinanceApprover' && d.status==='REQUESTED'" label="Xác nhận đã nhận" :loading="busy" text @click="approve(d)"/></template></Column></DataTable></section><div class="info-box page-info"><i class="pi pi-shield"></i><p>Danh sách hiển thị tối đa 100 khoản thu và 50 bút toán gần nhất; số tổng hợp tính trên toàn bộ chuyến trong vùng. Tiền mặt tài xế đã giữ được bù trừ vào quyền lợi; không cộng lần nữa vào số dư rút. Người lập đề nghị và người phê duyệt phải khác nhau.</p></div></template><Dialog v-model:visible="show" modal header="Đề nghị xác nhận nộp công nợ" :style="{width:'500px'}"><label>Tài xế<Select v-model="form.driverId" :options="data?.drivers??[]" option-label="name" option-value="id" filter class="full-width"/></label><label>Số tiền (VND)<InputNumber v-model="form.amount" :min="1" class="full-width"/></label><label>Mã tham chiếu ngân hàng<InputText v-model="form.reference" class="full-width"/></label><label>Bằng chứng kiểm tra<Textarea v-model="form.evidence" rows="3" class="full-width" placeholder="Thông tin đối chiếu thực tế, nguồn chứng từ…"/></label><template #footer><Button label="Quay lại" text severity="secondary" @click="show=false"/><Button label="Lập đề nghị" :loading="busy" :disabled="!form.driverId||form.amount<=0||!form.reference||form.evidence.length<5" @click="save"/></template></Dialog><Dialog v-model:visible="journalVisible" modal header="Chi tiết sổ cái" :style="{width:'650px'}"><template v-if="journal"><p>{{journal.description}}</p><code class="journal-key">{{journal.operationKey}}</code><DataTable :value="journal.entries" class="grap-table"><Column field="account" header="TÀI KHOẢN"/><Column header="NỢ"><template #body="{data:d}">{{money(d.debit)}}</template></Column><Column header="CÓ"><template #body="{data:d}">{{money(d.credit)}}</template></Column></DataTable><p class="muted">Bút toán đã post không thể chỉnh sửa hoặc xóa.</p></template></Dialog></template>
